import * as XLSX from './learningExcel';

export function mountLearning(host,{data,demo=false,request,schoolAccount=false}){
host.innerHTML='<div id="learning-studio"><main id="ls-main"></main><div id="ls-modal"></div><div class="ls-toast" role="status" aria-live="polite" hidden></div><input id="ls-image-input" type="file" accept="image/png,image/jpeg,image/webp,image/gif" hidden><input id="ls-import-input" type="file" accept=".xlsx,.csv" hidden></div>';
const controller=new AbortController(),listen=(target,event,callback)=>target.addEventListener(event,callback,{signal:controller.signal});
const root=host.querySelector('#learning-studio'),main=root.querySelector('#ls-main'),modal=root.querySelector('#ls-modal');
const paths={ 'arrow-left':'M20 12H4m6-6-6 6 6 6','arrow-right':'M4 12h16m-6-6 6 6-6 6','chevron-left':'m15 6-6 6 6 6','chevron-right':'m9 6 6 6-6 6',plus:'M12 4v16M4 12h16',check:'m4 12 5 5 11-11',x:'m6 6 12 12M6 18 18 6',pencil:'m4 16 12-12 4 4-12 12H4Zm9-9 4 4',ellipsis:'M4 12h1m6 0h1m6 0h1',search:'M16 16 21 21M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',folder:'M3 7V4h7l2 3h9v13H3Z',play:'m8 4 12 8-12 8Z','grip-vertical':'M9 4h1M14 4h1M9 10h1M14 10h1M9 16h1M14 16h1','trash-2':'M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15','triangle-alert':'m12 3 10 18H2ZM12 9v5m0 3h.1','undo-2':'M3 10h11a6 6 0 0 1 0 12M3 10l5-5M3 10l5 5','redo-2':'M21 10H10a6 6 0 0 0 0 12M21 10l-5-5M21 10l-5 5'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||'m12 3 10 6-10 6L2 9Zm-10 11 10 6 10-6M2 18l10 6 10-6'}"/></svg>`,btn=(a,t,c='',extra='')=>`<button type="button" class="cursor-interaction ${c}" data-action="${a}" ${extra}>${t}</button>`,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=[{id:'LP-GEO-001',title:'Coastal geography',subject:'Geography',year:'Y9',creator:'You',cards:[['Hydraulic action','Waves force water and air into cracks, weakening rock.'],['Abrasion','Sediment carried by waves scrapes and strikes the cliff.'],['Attrition','Rocks collide and become smaller, smoother and rounder.'],['Longshore drift','Angled swash and straight backwash move sediment along a beach.'],['Constructive waves','Stronger swash than backwash; deposit sediment and build beaches.'],['Wave-cut platform','A rocky platform left as repeated undercutting and collapse make a cliff retreat.'],['Happisburgh','A village in Norfolk vulnerable to erosion of soft, clay-rich cliffs.'],['Stack','An isolated rock pillar left when an arch roof collapses.']].map(([front,back])=>({front,back})),reviewed:0},{id:'LP-PHY-002',title:'Forces and motion',subject:'Physics',year:'Y9',creator:'You',cards:[['Force','A push or pull measured in newtons.'],['Resultant force','The overall force acting on an object.'],['Friction','A force that opposes movement between touching surfaces.'],['Balanced forces','Forces with a resultant of zero.']].map(([front,back])=>({front,back})),reviewed:0},{id:'LP-BIO-003',title:'Cells and organisation',subject:'Biology',year:'Y9',creator:'You',cards:[['Nucleus','Contains genetic material and controls cell activities.'],['Cell membrane','Controls what enters and leaves the cell.'],['Mitochondria','The site of aerobic respiration.']].map(([front,back])=>({front,back})),reviewed:0},{id:'LP-FRE-004',title:'Everyday French',subject:'French',year:'Y9',creator:'You',cards:[['Bonjour','Hello.'],['Merci','Thank you.'],['À bientôt','See you soon.']].map(([front,back])=>({front,back})),reviewed:0}];
let packs=data?.packs||(demo?defaults:[]),screen='home',active=defaults[0].id,draft=null,selected=-1,undo=[],redo=[],popup='',method='Flashcards',scope='All cards',studyIndex=0,correct=0,wrong=0,flipped=false,answered=false,studyCards=[],sessionResults=[],sessionTimes=[],questionStarted=performance.now(),questionElapsed=0,imagePending=null,importRows=[],dragFrom=-1,expanded=false;
const clone=o=>JSON.parse(JSON.stringify(o)),pack=()=>packs.find(p=>p.id===active)||packs[0];
let sessionId=null,realPeople=data?.people||[],busy=false;
function saveState(){if(demo)localStorage.setItem('rptpc-learning-demo',JSON.stringify({packs}));}
function icons(){}
async function persistPack(value){if(demo){value.owned=true;value.public=!!value.public;value.cards=value.cards.map(c=>({...c,cardId:c.cardId||crypto.randomUUID()}));return value}return (await request('POST','/api/learning/packs'+(value.dbId?'/'+value.dbId:''),{...value,public:!!value.public})).pack;}
async function refreshLibrary(){if(!demo){const fresh=await request('GET','/api/learning');packs=fresh.packs;realPeople=fresh.people;}}
function toast(t){const e=root.querySelector('.ls-toast');e.textContent=t;e.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.hidden=true,2800)}
function openPack(id){active=id;screen='pack';popup='';render();saveState()}
function render(){if(screen==='home')home();else if(screen==='pack')detail();else if(screen==='edit')editor();else if(screen==='study')study();else if(screen==='bank')bank();else if(screen==='search')searchPage();else library();icons()}
function tile(p){return btn('pack',`<span class="ls-pack-icon">${icon('layers')}</span><span><strong>${esc(p.title)}</strong><small>${esc(p.subject)} · ${esc(p.year)} · ${p.cards.length} cards</small></span>`,'ls-pack',`data-id="${esc(p.id)}"`)}
let searchQuery='',searchSort='newest',searchTypes=new Set(['sets','users','questions']);
function searchForm(){return `<form class="ls-global-search" aria-label="Search learning"><label class="ls-search-field">${icon('search')}<input aria-label="Search sets, users or pack code" maxlength="160" placeholder="Search sets, users or paste a code" value="${esc(searchQuery)}" autocomplete="off"></label></form>`}
function normalise(t){return String(t).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function typoDistance(a,b){const d=Array.from({length:a.length+1},()=>Array(b.length+1).fill(0));for(let i=0;i<=a.length;i++)d[i][0]=i;for(let j=0;j<=b.length;j++)d[0][j]=j;for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++){d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1));if(i>1&&j>1&&a[i-1]===b[j-2]&&a[i-2]===b[j-1])d[i][j]=Math.min(d[i][j],d[i-2][j-2]+1)}return d[a.length][b.length]}
function searchScore(text,query){const hay=normalise(text),q=normalise(query);if(!q)return -1;if(hay.includes(q))return 100;const words=hay.split(' '),tokens=q.split(' ');let cost=0;for(const token of tokens){const best=Math.min(...words.map(w=>w.startsWith(token)?0:typoDistance(w,token)));if(best>(token.length>=7?2:token.length>=4?1:0))return -1;cost+=best}return 70-cost*10}
function searchItems(){addLibrarySamples();const list=packs.map(p=>({type:'sets',id:p.id,title:p.title,subtitle:`${p.subject} · ${p.year} · ${p.cards.length} cards · By ${p.creator}`,text:`${p.title} ${p.subject} ${p.year} ${p.creator} ${p.creatorName||""} ${p.id}`,date:p.createdAt||0}));const people=demo?[...new Set(packs.map(p=>p.creator))].map(name=>({id:name,name})):realPeople;people.forEach(person=>list.push({type:'users',id:person.id,title:person.name,subtitle:`${packs.filter(p=>p.creator===person.name||p.creatorName===person.name).length} learning packs`,text:person.name,date:person.createdAt?new Date(person.createdAt).getTime():0}));function walk(nodes,path=[],names=[]){nodes.forEach((n,i)=>{const next=[...path,i],labels=[...names,n.name];if(n.children)walk(n.children,next,labels);else list.push({type:'questions',id:next.join('/'),title:labels.slice(-2).join(' · '),subtitle:labels.slice(0,-2).join(' / ')+` · ${n.count} questions`,text:labels.join(' '),date:0,path:next.slice(0,-1)})})}walk(bankTree);return list}
function searchResults(){const q=normalise(searchQuery),exact=packs.find(p=>normalise(p.id)===q);let rows=searchItems().filter(x=>searchTypes.has(x.type)).map(x=>({...x,score:exact?(x.type==='sets'&&x.id===exact.id?200:-1):searchScore(x.text,searchQuery)})).filter(x=>x.score>=0);return rows.sort((a,b)=>searchSort==='alphabetical'?a.title.localeCompare(b.title):searchSort==='oldest'?a.date-b.date||b.score-a.score:b.date-a.date||b.score-a.score)}
function filterPopup(){return `<div class="ls-pop ls-search-filter"><strong>Sort by</strong>${[['newest','Newest'],['oldest','Oldest'],['alphabetical','Alphabetical']].map(([v,label])=>`<label><input type="radio" name="search-sort" value="${v}" ${searchSort===v?'checked':''}>${label}</label>`).join('')}<hr><strong>Show</strong>${[['users','Users'],['sets','Sets'],['questions','Questions']].map(([v,label])=>`<label><input type="checkbox" data-search-type="${v}" ${searchTypes.has(v)?'checked':''}>${label}</label>`).join('')}</div>`}
function searchPage(){const results=searchResults();main.innerHTML=`${btn('home',icon('arrow-left')+'Your learning')}<div class="ls-heading" style="margin-top:22px"><div><h1>Search results</h1><p class="ls-muted">${results.length} results for “${esc(searchQuery)}”</p></div>${searchForm()}</div><div class="ls-row ls-search-tools"><div class="ls-anchor">${btn('search-filter',icon('list-filter')+'Filter','','aria-expanded="'+(popup==='search-filter')+'"')}${popup==='search-filter'?filterPopup():''}</div><small>${searchSort==='alphabetical'?'Alphabetical':searchSort==='oldest'?'Oldest first':'Newest first'}</small></div><div class="ls-search-results">${results.length?results.map(r=>btn('search-result',`<span class="ls-search-icon">${icon(r.type==='users'?'user-round':r.type==='sets'?'layers':'files')}</span><span><small>${r.type==='users'?'USER':r.type==='sets'?'LEARNING PACK':'QUESTION SET'}</small><strong>${esc(r.title)}</strong><small>${esc(r.subtitle)}</small>${r.type==='sets'?`<small>${esc(r.id)}</small>`:''}</span><span class="ls-result-arrow">${icon('chevron-right')}</span>`,'ls-search-result',`data-type="${r.type}" data-id="${esc(r.id)}"`)).join(''):'<div class="ls-panel ls-library-empty"><h2>No matches yet</h2><p class="ls-muted">Try a title, subject, creator name or pack code.</p></div>'}</div>`}
async function performSearch(){if(!searchQuery.trim())return;try{if(!demo){const query=searchQuery;const found=await request('GET','/api/learning/search?q='+encodeURIComponent(query.trim()));if(query!==searchQuery||controller.signal.aborted)return;for(const p of found.packs){const i=packs.findIndex(x=>x.id===p.id);if(i<0)packs.push(p);else packs[i]=p}for(const person of found.people)if(!realPeople.some(p=>p.id===person.id))realPeople.push(person)}screen='search';popup='';render()}catch(e){toast(e.message)}}
listen(root,'submit',e=>{if(!e.target.matches('.ls-global-search'))return;e.preventDefault();searchQuery=e.target.querySelector('input').value.trim();performSearch()});
listen(root,'keydown',e=>{if(e.key!=='Enter'||!e.target.matches('.ls-global-search input'))return;e.preventDefault();searchQuery=e.target.value.trim();performSearch()});
listen(root,'input',e=>{if(!e.target.matches('.ls-global-search input'))return;searchQuery=e.target.value;const exact=packs.find(p=>normalise(p.id)===normalise(searchQuery));if(exact){screen='search';searchTypes.add('sets');popup='';render()}else if(/^LP-[a-f0-9]{10}$/i.test(searchQuery.trim())){searchTypes.add('sets');performSearch()}});
listen(root,'change',e=>{if(e.target.hasAttribute('data-public')){snapshot();draft.public=e.target.checked;}if(e.target.name==='search-sort'){searchSort=e.target.value;render()}if(e.target.dataset.searchType){const type=e.target.dataset.searchType;if(e.target.checked)searchTypes.add(type);else searchTypes.delete(type);render()}});
function home(){const recent=packs.filter(p=>p.lastStudied).sort((a,b)=>b.lastStudied-a.lastStudied)[0];const p=recent||packs.find(p=>p.owned)||packs[0];if(!p){main.innerHTML=`<div class="ls-heading"><div><h1>Your learning</h1><p class="ls-muted">Create a pack to get started.</p></div>${searchForm()}</div><section class="ls-panel ls-library-empty"><h2>Your study space is ready</h2>${btn('create',icon('plus')+'Create learning pack','ls-primary')} ${btn('library','Library')} ${btn('bank','Question bank')}</section>`;return}active=p.id;main.innerHTML=`<div class="ls-heading"><div><span class="ls-tag">STUDY MODE</span><h1>Your learning</h1><p class="ls-muted">Pick up where you left off.</p></div>${searchForm()}</div><section class="ls-panel ls-feature"><div><small>${recent?'LAST STUDIED LEARNING PACK':'YOUR LEARNING PACK'}</small><div class="ls-title">${esc(p.title)}</div><p>${esc(p.subject)} · ${esc(p.year)} · ${p.cards.length} cards</p></div>${btn('pack','Open learning pack '+icon('arrow-right'),'ls-primary',`data-id="${p.id}"`)}</section><div class="ls-shortcuts">${btn('create',icon('plus')+'<strong>Create learning pack</strong><small>Build your own flashcards</small>','ls-shortcut')}${btn('bank',icon('folder-tree')+'<strong>Question bank</strong><small>Explore subjects and topics</small>','ls-shortcut')}${btn('library',icon('library')+'<strong>Library</strong><small>All your learning packs</small>','ls-shortcut')}</div><div class="ls-row"><h2>Recent learning packs</h2>${btn('library','View all '+icon('arrow-right'))}</div><div class="ls-packs">${packs.filter(p=>p.inLibrary!==false).slice(0,4).map(tile).join('')}</div><div class="ls-twocol"><section class="ls-panel"><span class="ls-tag">QUICK REVIEW</span><h2>Keep it fresh</h2><p class="ls-muted">A short practice session with ${esc(p.title.toLowerCase())}.</p>${btn('quick','Review cards','ls-primary')}</section>${schoolAccount?'<section class="ls-panel"><span class="ls-tag">UPCOMING ASSESSMENTS</span><h2>Assessment reminders</h2><p class="ls-muted">No assessments linked to this learning pack yet.</p><small>Your school assignments are available in School.</small></section>':''}</div><section class="ls-panel"><h2>People you might know</h2>${realPeople.length?realPeople.slice(0,3).map(person=>`<div class="ls-person"><span class="ls-avatar">${esc(person.name.slice(0,2).toUpperCase())}</span><div><strong>${esc(person.name)}</strong><small>Public community profile</small></div>${btn('find-person','Find packs','','data-name="'+esc(person.name)+'"')}</div>`).join(''):'<p class="ls-muted">Public community profiles will appear here.</p>'}</section>`}
function menu(){return `<div class="ls-pop right">${btn('copy',icon('copy')+'Copy pack')}${btn('share',icon('share-2')+'Share pack')}${btn('importfile',icon('sheet')+'Import from Excel file')}${btn('template',icon('download')+'Download Excel template')}</div>`}
function detail(){const p=pack();main.innerHTML=`${btn('home',icon('arrow-left')+'Learning')}<div class="ls-pack-heading"><div class="ls-pack-title"><h1>${esc(p.title)}</h1><div class="ls-muted">Created by ${esc(p.creator)} · ${esc(p.subject)} · ${esc(p.year)}</div><small>${esc(p.id)}</small></div><div class="ls-pack-tools"><div class="ls-anchor">${btn('menu',icon('ellipsis'),'','aria-label="Pack options" aria-expanded="'+(popup==='menu')+'"')}${popup==='menu'?menu():''}</div>${btn('edit',icon('pencil'),'','aria-label="Edit learning pack" '+(pack().owned===false?'disabled':''))}</div></div><section class="ls-panel"><div class="ls-row"><div><span class="ls-tag">YOUR NEXT SESSION</span><h2>Ready to learn?</h2><p class="ls-muted">${p.cards.length} cards · Start here, without leaving your pack.</p></div>${btn('start',icon('play')+'Start studying','ls-primary')}</div><small>Study method</small><div class="ls-study-choice">${['Flashcards','Absorb','Quiz','Timed test'].map(m=>btn('method',m,method===m?'ls-active':'',`data-value="${m}" aria-pressed="${method===m}"`)).join('')}</div><small>Cards to practise</small><div class="ls-study-choice">${['Due for review','All cards','Difficult cards'].map(s=>btn('scope',s,scope===s?'ls-active':'',`data-value="${s}" aria-pressed="${scope===s}"`)).join('')}</div><div class="ls-track"><div style="width:${Math.min(100,(p.reviewed||0)/Math.max(1,p.cards.length)*100)}%"></div></div><small>${p.reviewed||0} of ${p.cards.length} cards practised</small></section>${hardestTerms()}<section class="ls-panel"><div class="ls-row"><h2>Cards <span class="ls-muted">(${p.cards.length})</span></div><input aria-label="Search cards" class="ls-search" id="ls-card-search" placeholder="Search terms or definitions"><div class="ls-cardlist" id="ls-card-list">${cardList(p.cards)}</div></section>`}
function cardList(cards){return cards.map((c,i)=>`<div class="ls-carditem"><small>${i+1}</small><strong>${esc(c.front)}</strong><p>${esc(c.back)}${c.image?`<img class="ls-image-preview" src="${c.image}" alt="Card image on ${esc(c.side)}">`:''}</p></div>`).join('')||'<p class="ls-muted">No cards yet. Add your first card to start studying.</p>'}
function startEdit(){if(pack().owned===false){toast('Copy this pack to edit your own version.');return}draft=clone(pack());selected=-1;undo=[];redo=[];screen='edit';popup='';render()}
function snapshot(){undo.push(clone(draft));if(undo.length>40)undo.shift();redo=[]}
function issues(){let seen=new Set(),out=[];draft.cards.forEach((c,i)=>{if(!c.front.trim())out.push({i,col:'front',text:'Missing front / term'});if(!c.back.trim())out.push({i,col:'back',text:'Missing back / definition'});let key=c.front.trim().toLowerCase();if(key&&seen.has(key))out.push({i,col:'front',text:'Duplicate term'});seen.add(key)});return out}
function editor(){const warn=issues();main.innerHTML=`<div class="ls-heading"><div><span class="ls-tag">LEARNING PACK EDITOR</span><h1>Edit your flashcards</h1><small>${esc(draft.id)} · ${draft.cards.length} cards</small></div><div class="ls-actions">${btn('cancel-edit','Cancel')}${btn('save',icon('check')+'Save changes','ls-primary')}</div></div><div class="ls-meta"><label>Pack title<input autocomplete="off" data-meta="title" value="${esc(draft.title)}"></label><label>Subject<input autocomplete="off" data-meta="subject" value="${esc(draft.subject)}"></label><label>Year group<input autocomplete="off" data-meta="year" value="${esc(draft.year)}"></label></div><label class="ls-share-control"><input type="checkbox" data-public ${draft.public?'checked':''}> Public pack · Anyone signed in can find and study it</label><div class="ls-toolbar">${btn('undo',icon('undo-2'),'','aria-label="Undo (Ctrl+Z)" '+(!undo.length?'disabled':''))}${btn('redo',icon('redo-2'),'','aria-label="Redo (Ctrl+Y)" '+(!redo.length?'disabled':''))}${btn('newcard',icon('plus')+'New flashcard')}${btn('import',icon('sheet')+'Import flashcards')}${btn('image',icon('image-plus')+'Add image','',selected<0?'disabled':'')}<span class="ls-spacer"></span><div class="ls-anchor">${btn('issues',icon('triangle-alert')+'<span data-issue-count>'+warn.length+'</span>','ls-issue','aria-label="'+warn.length+' card issues" aria-expanded="'+(popup==='issues')+'"')}${popup==='issues'?`<div class="ls-pop right"><strong style="display:block;padding:8px">Card checks</strong>${warn.length?warn.map(w=>btn('jump',`Card ${w.i+1}: ${w.text}`,'',`data-row="${w.i}" data-col="${w.col}"`)).join(''):'<p style="padding:8px">No issues found.</p>'}</div>`:''}</div></div><div class="ls-table-wrap"><table class="ls-table"><colgroup><col style="width:35px"><col style="width:40px"><col><col><col style="width:65px"><col style="width:35px"></colgroup><thead><tr><th aria-label="Reorder"></th><th>#</th><th>Front / term</th><th>Back / definition</th><th>Image</th><th></th></tr></thead><tbody>${draft.cards.map((c,i)=>`<tr data-row="${i}" class="${selected===i?'selected':''}"><td><button class="ls-grip" draggable="true" data-drag="${i}" aria-label="Drag card ${i+1} to reorder">${icon('grip-vertical')}</button></td><td>${btn('select',i+1,'ls-rownum',`data-row="${i}" aria-label="Select card ${i+1}"`)}</td><td><textarea aria-label="Card ${i+1} front" data-cell="front" data-row="${i}">${esc(c.front)}</textarea></td><td><textarea aria-label="Card ${i+1} back" data-cell="back" data-row="${i}">${esc(c.back)}</textarea></td><td>${c.image?btn('image-edit',`<img class="ls-thumb" src="${c.image}" alt="${esc(c.side)} image"><small>${esc(c.side)}</small>`,'',`data-row="${i}"`):'<small>—</small>'}</td><td>${btn('delete',icon('trash-2'),'','data-row="'+i+'" aria-label="Delete card '+(i+1)+'"')}</td></tr>`).join('')}</tbody></table></div><p class="ls-edit-note">Drag the left handle to reorder · Select a row to add an image · Paste two columns from Excel · Ctrl+Z / Ctrl+Y · Ctrl+S</p>`}
function closeModal(){modal.innerHTML='';imagePending=null}
function dialog(title,content,actions=''){modal.innerHTML=`<div class="ls-overlay"><section class="ls-dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="ls-row"><h2>${title}</h2>${btn('close',icon('x'),'','aria-label="Close popup"')}</div>${content}<div class="ls-actions">${actions}</div></section></div>`;icons();const focus=modal.querySelector('input,textarea,button');focus?.focus()}
function create(){dialog('Create learning pack',`<label><span>Pack title</span><input autocomplete="off" id="ls-newtitle" placeholder="e.g. Coastal geography"></label><label><span>Subject</span><input autocomplete="off" id="ls-newsubject" placeholder="e.g. Geography"></label><label><span>Year group</span><input autocomplete="off" id="ls-newyear" placeholder="e.g. Y9"></label><small>Every pack receives its own unique ID.</small>`,btn('close','Cancel')+btn('create-confirm','Create & add cards','ls-primary'))}
function parseText(t){return t.trim().split(/\r?\n/).filter(l=>l.trim()).map(l=>{const cells=l.split(l.includes('\t')?'\t':'|');return {front:(cells[0]||'').trim(),back:cells.slice(1).join(' | ').trim()}})}
function importDialog(){dialog('Import flashcards',`<p class="ls-muted">Paste two columns, or use term | definition on each line.</p><textarea id="ls-paste" rows="6" placeholder="Hydraulic action | Waves force water into cracks.\nAbrasion | Sediment scrapes the cliff."></textarea><div class="ls-actions">${btn('importfile',icon('upload')+'Choose XLSX / CSV')}</div>`,btn('close','Cancel')+btn('preview-paste','Preview import','ls-primary'))}
function previewImport(){dialog('Review your import',`<p>${importRows.length} flashcards · Added after your existing cards</p><div class="ls-import-preview">${importRows.map((c,i)=>`<div class="ls-import-row"><strong>${i+1}. ${esc(c.front)||'⚠ Missing term'}</strong><small>${esc(c.back)||'⚠ Missing definition'}</small></div>`).join('')}</div>`,btn('close','Cancel')+btn('confirm-import','Import '+importRows.length+' cards','ls-primary',!importRows.length?'disabled':''))}
function imageDialog(){dialog('Which side should show the image?',`<img class="ls-image-preview" src="${imagePending}" alt="Selected image preview"><div class="ls-selectside">${btn('image-front','Front','ls-primary')}${btn('image-back','Back','ls-primary')}</div>`)}
async function template(){if(!XLSX){toast('Excel library is unavailable. Paste cards or import CSV instead.');return}const book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,XLSX.utils.aoa_to_sheet([['Front','Back'],['Hydraulic action','Waves force water and air into cracks.'],['Abrasion','Sediment scrapes the cliff.']]),'Flashcards');XLSX.utils.book_append_sheet(book,XLSX.utils.aoa_to_sheet([['Instructions'],['Put one flashcard on each row of the Flashcards sheet.'],['Front is the term or question. Back is the definition or answer.'],['Replace the example rows. Add images in the pack editor.']]),'Instructions');await XLSX.writeFile(book,'Learning-pack-template.xlsx');popup='';render()}
function shuffle(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
async function studyStart(){const p=pack();let source=p.cards.map((c,i)=>({...c,index:i}));if(scope==='Difficult cards')source=source.filter(c=>c.difficult).sort((a,b)=>hardness(b)-hardness(a));if(scope==='Due for review')source=source.filter(c=>!c.mastered);if(!source.length){toast('No cards in this selection. Try All cards.');return}if(method==='Absorb'&&new Set(p.cards.map(c=>c.back.trim())).size<2){toast('Absorb needs at least two different answers for multiple choice.');return}studyCards=[];if(method==='Absorb'){for(let i=0;i<source.length;i+=5){const batch=source.slice(i,i+5);studyCards.push(...batch.map(c=>({...c,phase:'choice',batch:Math.floor(i/5)+1,options:shuffle([c.back,...shuffle([...new Set(p.cards.map(x=>x.back).filter(x=>x.trim()&&x!==c.back))]).slice(0,3)])})),...batch.map(c=>({...c,phase:'recall',batch:Math.floor(i/5)+1})))}}else studyCards=source;studyCards=studyCards.map((c,i)=>({...c,questionKey:i}));if(!demo){if(!p.dbId){toast('Save this pack before studying.');return}sessionId=crypto.randomUUID();await request('POST','/api/learning/sessions',{id:sessionId,pack:p.dbId,method,questions:studyCards.map(c=>({cardId:c.cardId,phase:c.phase||(['Quiz','Timed test'].includes(method)?'written':'recall')}))})}studyIndex=0;correct=0;wrong=0;sessionResults=studyCards.map(()=>null);sessionTimes=studyCards.map(()=>0);resetQuestionClock();flipped=false;answered=false;p.lastStudied=Date.now();screen='study';render();saveState()}
function resetQuestionClock(){questionElapsed=0;questionStarted=document.hidden?null:performance.now()}
function questionSeconds(){return (questionElapsed+(questionStarted===null?0:performance.now()-questionStarted))/1000}
function hardness(c){const st=c.stats;if(!st?.attempts)return 0;const errorRate=(st.wrong+1)/(st.attempts+2),time=Math.min(1,st.seconds/st.attempts/45);return Math.round(100*(.65*errorRate+.35*time))}
function hardestTerms(){const ranked=pack().cards.filter(c=>c.stats?.attempts).sort((a,b)=>hardness(b)-hardness(a)).slice(0,3);return ranked.length?`<section class="ls-panel ls-hardest"><h2>Hardest terms so far</h2>${ranked.map(c=>`<div class="ls-hard-row"><strong>${esc(c.front)}</strong><small>${c.stats.correct} right / ${c.stats.wrong} wrong · ${Math.round(c.stats.seconds/c.stats.attempts)}s average · Difficulty ${hardness(c)}/100</small></div>`).join('')}<small>Ranked by errors (65%) and average active time (35%). Early results may change as you practise.</small></section>`:''}
async function recordAnswer(value){const card=pack().cards[studyCards[studyIndex].index],old=sessionResults[studyIndex],time=questionSeconds()+(studyCards[studyIndex].deferredSeconds||0);if(!demo)await request('POST','/api/learning/sessions/'+sessionId+'/answers',{question:studyCards[studyIndex].questionKey,correct:value,seconds:Math.min(3600,time)});const st=card.stats||(card.stats={attempts:0,correct:0,wrong:0,seconds:0});if(old!==null){st[old?'correct':'wrong']--;st.seconds-=sessionTimes[studyIndex]}else st.attempts++;st[value?'correct':'wrong']++;st.seconds+=time;sessionResults[studyIndex]=value;sessionTimes[studyIndex]=time;correct=sessionResults.filter(v=>v===true).length;wrong=sessionResults.filter(v=>v===false).length;card.difficult=st.wrong/st.attempts>=.25||(st.attempts>=2&&st.seconds/st.attempts>25);card.mastered=!card.difficult&&value;pack().reviewed=pack().cards.filter(c=>c.stats?.attempts).length;saveState()}
function absorbNext(){return btn('next-card','Next question '+icon('arrow-right'),'ls-primary')+'<small style="margin-top:8px">Enter to continue</small>'}
function postponeButton(){return `<div class="ls-postpone">${btn('postpone','Answer next time','',''+(studyIndex>=studyCards.length-1?'disabled':''))}<small>Returns after 3 more questions, or at the end if fewer remain.</small></div>`}
function postponeQuestion(){if(method!=='Absorb'||sessionResults[studyIndex]!==null||studyIndex>=studyCards.length-1)return;const current=studyCards.splice(studyIndex,1)[0];current.deferredSeconds=(current.deferredSeconds||0)+questionSeconds();const result=sessionResults.splice(studyIndex,1)[0],time=sessionTimes.splice(studyIndex,1)[0],destination=Math.min(studyIndex+3,studyCards.length);studyCards.splice(destination,0,current);sessionResults.splice(destination,0,result);sessionTimes.splice(destination,0,time);resetQuestionClock();flipped=false;answered=false;render();toast('Question postponed. Your score is unchanged.')}
listen(document,'keydown',e=>{if(screen!=='study'||method!=='Absorb'||e.key!=='Enter'||modal.innerHTML)return;if(document.activeElement!==document.body&&!root.contains(document.activeElement))return;e.preventDefault();if(e.repeat||sessionResults[studyIndex]===null||!studyCards[studyIndex])return;studyIndex++;resetQuestionClock();flipped=false;answered=false;render()});
function absorbChoice(c){const result=sessionResults[studyIndex];return `<div class="ls-panel ls-absorb"><span class="ls-tag">BATCH ${c.batch} · MULTIPLE CHOICE</span><h2>${esc(c.front)}</h2><p class="ls-muted">Choose the matching definition.</p>${c.image&&c.side==='Front'?`<img class="ls-image-preview" src="${c.image}" alt="Question illustration">`:''}<div class="ls-choices">${c.options.map((option,i)=>btn('choose-answer',`<span class="ls-option-letter">${String.fromCharCode(65+i)}</span><span>${esc(option)}</span>`,result!==null&&option===c.back?'ls-choice-correct':'',`data-option="${i}" ${result!==null?'disabled':''}`)).join('')}</div>${result!==null?`<div class="ls-choice-feedback" role="status"><strong>${result?'Correct!':'Not quite.'}</strong>${!result?`<p>The answer is: ${esc(c.back)}</p>`:''}${absorbNext()}</div>`:postponeButton()}</div>`}
listen(document,'visibilitychange',()=>{if(screen!=='study')return;if(document.hidden){if(questionStarted!==null)questionElapsed+=performance.now()-questionStarted;questionStarted=null}else questionStarted=performance.now()});

function sessionStats(){const total=studyCards.length,done=correct+wrong,accuracy=done?Math.round(correct/done*100):0,progress=total?Math.round(done/total*100):0;return `<div class="ls-session-stats" aria-live="polite"><div><small>${method==='Absorb'?'Questions left':'Cards left'}</small><strong>${total-done}</strong></div><div><small>Correct</small><strong>${correct}</strong></div><div><small>Incorrect</small><strong>${wrong}</strong></div><div><small>Accuracy</small><strong>${done?accuracy+'%':'—'}</strong><small>${correct} / ${done} answered</small></div></div><div class="ls-row ls-progress-label"><span>Progress</span><span>${done} / ${total} · ${progress}%</span></div><div class="ls-track" role="progressbar" aria-label="Session progress" aria-valuenow="${done}" aria-valuemin="0" aria-valuemax="${total}"><div style="width:${progress}%"></div></div>`}
function answerButtons(){return btn('again',icon('x')+'Got it wrong')+btn('got',icon('check')+'Got it right','ls-primary')}
function study(){const c=studyCards[studyIndex];main.innerHTML=`<div class="ls-study-shell"><div class="ls-heading">${btn('backpack',icon('arrow-left')+'Back to pack')}<small>${esc(method)}${c?' · '+(method==='Absorb'?'Question ':'Card ')+(studyIndex+1)+' of '+studyCards.length:''}</small></div><div class="ls-study-title"><span class="ls-tag">${c?'STUDY SESSION':correct+wrong===studyCards.length?'SESSION COMPLETE':'END OF CARDS'}</span><h1>${esc(pack().title)}</h1></div>${sessionStats()}${!c?`<section class="ls-panel ls-library-empty"><h2>Nice work!</h2><p>You answered ${correct+wrong} of ${studyCards.length} ${method==='Absorb'?'questions':'cards'}${correct+wrong<studyCards.length?`; ${studyCards.length-correct-wrong} left unanswered`:""}.</p>${correct+wrong<studyCards.length?btn('review-unanswered','Review skipped cards','ls-primary'):""}${method==='Absorb'?'':btn('previous-card','Back to last card')}${btn('restart','Study again','ls-primary')} ${btn('backpack','Return to pack')}</section>${hardestTerms()}`:c.phase==='choice'?absorbChoice(c):`${c.phase==='recall'?`<p class="ls-phase-label">Batch ${c.batch} · Recall the same terms in the same order</p>`:''}<div class="ls-card-stage ${method==='Absorb'?'ls-absorb-stage':''}">${method==='Absorb'?'':btn('previous-card',icon('chevron-left'),'ls-card-arrow','aria-label="Previous flashcard" '+(studyIndex===0?'disabled':''))}<div class="ls-flipper ${flipped?'flipped':''}"><section class="ls-panel ls-face ls-front" ${flipped?'aria-hidden="true"':''}><small>FRONT / TERM</small><div>${esc(c.front)}</div>${c.image&&c.side==='Front'?`<img class="ls-image-preview" src="${c.image}" alt="Flashcard front illustration">`:''}</section><section class="ls-panel ls-face ls-back" ${!flipped?'aria-hidden="true"':''}><small>BACK / DEFINITION</small><div>${esc(c.back)}</div>${c.image&&c.side==='Back'?`<img class="ls-image-preview" src="${c.image}" alt="Flashcard back illustration">`:''}</section></div>${method==='Absorb'?'':btn('next-card',icon('chevron-right'),'ls-card-arrow','aria-label="Next flashcard / skip"')}</div>${sessionResults[studyIndex]!==null?`<small class="ls-rated">Marked ${sessionResults[studyIndex]?'correct':'incorrect'}${method==='Absorb'?'':' · Changing it updates your score.'}</small>`:''}${method==='Flashcards'||c.phase==='recall' ?`<div class="ls-actions ls-study-controls" id="ls-answer-controls">${method==='Absorb'&&sessionResults[studyIndex]!==null?absorbNext():!flipped?btn('flip',icon('rotate-3d')+'Show answer','ls-primary'):answerButtons()}</div><small class="ls-study-hint">${method==='Absorb'&&sessionResults[studyIndex]!==null?'Answer recorded. Press Enter to continue.':flipped?'Rate your answer from memory.':'Think of the answer, then flip the card.'}</small>`:`<section class="ls-panel"><label>Your answer<textarea id="ls-study-answer" placeholder="Write your answer from memory"></textarea></label><div class="ls-actions ls-study-controls" style="margin-top:12px">${!answered?btn('check-answer','Compare with answer','ls-primary'):answerButtons()}</div>${answered?`<p style="margin-top:14px"><strong>Model answer:</strong> ${esc(c.back)}</p>`:''}</section>`}${method==='Absorb'&&sessionResults[studyIndex]===null?postponeButton():''}${method==='Timed test'?'<small>Preview of the written test flow · Timer and automatic marking are not connected.</small>':''}`}</div>`}
const bankSubjects={Physics:{Forces:['Potential forces','Balanced and unbalanced forces'],Energy:['Energy stores']},Geography:{Coasts:['Coastal processes','Happisburgh'],Rivers:['River processes']},Biology:{Cells:['Cell structure','Specialised cells']},Chemistry:{Particles:['States of matter']},Maths:{Algebra:['Expressions','Equations']}};
const difficulties=()=>['Easy','Medium','Hard','Challenge'].map((name,i)=>({name,type:'Question set',count:[6,4,3,2][i]}));
const topicsFor=topics=>topics.map(name=>({name,type:'Topic',children:difficulties()}));
const unitsFor=units=>Object.entries(units).map(([name,topics])=>({name,type:'Unit',children:topicsFor(topics)}));
const bankTree=Object.entries(bankSubjects).map(([name,units])=>({name,type:'Subject',children:['Y9','Y10'].map(name=>({name,type:'Year group',children:unitsFor(units)}))}));
bankTree.push({name:'IGCSE',type:'Qualification',children:[{name:'Past papers',type:'Folder',children:['November 2025','June 2025','January 2025','November 2024','June 2024','January 2024'].map(name=>({name,type:'Exam session',children:[]}))}]});
let bankPath=[],bankSelected=new Set(),bankLastSelect=-1;
function bankChildren(path=bankPath){let nodes=bankTree;for(const i of path)nodes=nodes[i].children||[];return nodes}
function bankLeaves(node,key){return node.children?node.children.flatMap((c,i)=>bankLeaves(c,key+'/'+i)):[{key,count:node.count}]}
function bankTotals(){let total=0;bankTree.forEach((n,i)=>bankLeaves(n,String(i)).forEach(l=>{if(bankSelected.has(l.key))total+=l.count}));return total}
function bank(){const nodes=bankChildren();let cursor=bankTree;const crumbs=bankPath.map((i,depth)=>{const n=cursor[i];cursor=n.children;return `<span aria-hidden="true">/</span>${btn('bank-crumb',esc(n.name),'',`data-depth="${depth+1}"`)}` }).join('');main.innerHTML=`${btn('home',icon('arrow-left')+'Learning')}<div class="ls-heading" style="margin-top:20px"><div><h1>Question bank</h1><p class="ls-muted">${bankPath.length?'Open a folder or select question sets.':'Choose a subject to get started.'}</p></div></div><div class="ls-bank-controls">${btn('bank-back',icon('arrow-left'),'','aria-label="Previous folder" '+(!bankPath.length?'disabled':''))}<nav class="ls-breadcrumbs" aria-label="Question folder path">${btn('bank-crumb','Subjects','','data-depth="0"')}${crumbs}</nav></div><table class="ls-bank-table"><thead><tr><th aria-label="Select"></th><th>Name</th><th class="ls-bank-type">Type</th><th class="ls-bank-count">Questions</th></tr></thead><tbody>${nodes.map((n,i)=>{const key=[...bankPath,i].join('/'),leaves=bankLeaves(n,key),chosen=leaves.filter(l=>bankSelected.has(l.key)).length;return `<tr><td><input type="checkbox" data-bank-check="${i}" aria-label="Select ${esc(n.name)}" ${leaves.length&&chosen===leaves.length?'checked':''} ${chosen&&chosen<leaves.length?'data-partial="true"':''}></td><td>${btn(n.children?'bank-open':'bank-set',icon(n.children?'folder':'files')+esc(n.name)+(n.children?`<span class="ls-chevron">${icon('chevron-right')}</span>`:''),'ls-bank-open',`data-index="${i}"`)}</td><td class="ls-bank-type">${esc(n.type)}</td><td class="ls-bank-count">${leaves.reduce((sum,l)=>sum+l.count,0)}</td></tr>`}).join('')}${!nodes.length?'<tr><td colspan="4"><div class="ls-library-empty"><h3>This folder is empty</h3><p class="ls-muted">Past papers will be added here later.</p></div></td></tr>':''}</tbody></table><div class="ls-bank-footer"><span aria-live="polite">${bankSelected.size} sets selected · ${bankTotals()} questions</span><div class="ls-actions">${btn('bank-clear','Deselect all','',!bankSelected.size?'disabled':'')}${btn('bank-practice',icon('play')+'Practise selected','ls-primary',!bankSelected.size?'disabled':'')}</div></div><small style="margin-top:12px">Sample question folders · Select a folder to include its sets. Shift-click checkboxes to select a range.</small>`;main.querySelectorAll('[data-partial]').forEach(e=>e.indeterminate=true)}
function addLibrarySamples(){if(!demo)return;const now=Date.now(),day=86400000;const shared=[{id:'LP-SHARED-GEO',title:'Coasts: key vocabulary',subject:'Geography',year:'Y9',creator:'Alex Morgan',cards:[{front:'Headland',back:'A section of land that extends into the sea.'},{front:'Bay',back:'An inlet of the sea where softer rock has eroded.'},{front:'Deposition',back:'Sediment is dropped when water loses energy.'}],createdAt:now-6*day,lastStudied:now-2*day,reviewed:0},{id:'LP-SHARED-PHY',title:'Energy stores',subject:'Physics',year:'Y9',creator:'Ms Patel',cards:[{front:'Kinetic energy store',back:'The energy store of a moving object.'},{front:'Gravitational potential energy store',back:'Energy stored by an object because of its height in a gravitational field.'},{front:'Elastic potential energy store',back:'Energy stored when an object is stretched or compressed.'}],createdAt:now-3*day,lastStudied:null,reviewed:0}];shared.forEach(p=>{if(!packs.some(x=>x.id===p.id))packs.push(p)});packs.forEach((p,i)=>{if(!p.createdAt)p.createdAt=now-(8+i)*day})}
function libraryDate(value){return value?new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Europe/Warsaw'}).format(new Date(value)):'Not studied yet'}
function library(){addLibrarySamples();const ordered=packs.filter(p=>p.inLibrary!==false).sort((a,b)=>(b.lastStudied||0)-(a.lastStudied||0)||(b.createdAt||0)-(a.createdAt||0));main.innerHTML=`${btn('home',icon('arrow-left')+'Learning')}<div class="ls-heading" style="margin-top:20px"><div><h1>Your library</h1><p class="ls-muted">Your packs and packs you study from others · Most recently studied first</p></div>${btn('create',icon('plus')+'Create pack','ls-primary')}</div><div class="ls-library-list"><div class="ls-library-head" aria-hidden="true"><span>Learning pack</span><span>Created by</span><span>Created</span><span>Last studied</span></div>${ordered.map(p=>btn('pack',`<span class="ls-library-name">${icon('layers')}<span><strong>${esc(p.title)}</strong><small>${esc(p.subject)} · ${esc(p.year)} · ${p.cards.length} cards</small></span></span><span><span class="ls-mobile-label">Created by:</span>${esc(p.creator)}</span><span class="ls-library-date"><span class="ls-mobile-label">Created:</span>${libraryDate(p.createdAt)}</span><span class="ls-library-date"><span class="ls-mobile-label">Last studied:</span>${libraryDate(p.lastStudied)}</span>`,'ls-library-item',`data-id="${esc(p.id)}"`)).join('')}</div><small style="margin-top:14px">${demo?"Demo data stays in this browser.":"Saved to your account."} Last studied updates when you start a session.</small>`}
listen(root,'click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(busy)return;try{
if(a==='expand'){expanded=!expanded;root.querySelector('.ls-nav').classList.toggle('expanded',expanded);return}
if(a==='home'||a==='library'||a==='bank'){if(screen==='edit'&&JSON.stringify(draft)!==JSON.stringify(pack())){dialog('Leave without saving?',`<p>Your unsaved edits will be discarded.</p>`,btn('close','Keep editing')+btn('discard-nav','Discard changes','',`data-target="${a}"`));return}if(a==='home'||a==='library')await refreshLibrary();screen=a;if(a==='bank'){bankPath=[];bankLastSelect=-1}popup='';render();saveState()}
else if(a==='discard-nav'){screen=b.dataset.target;closeModal();render()}
else if(a==='pack'){closeModal();openPack(b.dataset.id);}
else if(a==='create')create();
else if(a==='create-confirm'){const title=modal.querySelector('#ls-newtitle').value.trim();if(!title){modal.querySelector('#ls-newtitle').focus();toast('Give your pack a title.');return}const id='LP-'+Math.random().toString(36).slice(2,9).toUpperCase();packs.unshift({id,title,subject:modal.querySelector('#ls-newsubject').value.trim()||'General',year:modal.querySelector('#ls-newyear').value.trim()||'Personal',creator:'You',owned:true,public:false,inLibrary:true,createdAt:Date.now(),lastStudied:null,cards:[],reviewed:0});active=id;closeModal();startEdit();snapshot();draft.cards.push({front:'',back:''});selected=0;render();saveState()}
else if(a==='menu'){popup=popup==='menu'?'':'menu';render()}
else if(a==='edit')startEdit();
else if(a==='copy'){busy=true;const p=clone(pack());delete p.dbId;delete p.version;p.id='LP-'+Math.random().toString(36).slice(2,9).toUpperCase();p.title+=' (copy)';p.creator='You';p.owned=true;p.public=false;p.createdAt=Date.now();p.lastStudied=null;p.reviewed=0;p.inLibrary=true;p.cards=p.cards.map(({front,back,image,side})=>({front,back,...(image?{image,side}:{})}));const saved=await persistPack(p);packs.unshift(saved);openPack(saved.id);toast('Pack copied to your library.')}
else if(a==='share')dialog('Share learning pack',`<label>Pack ID<input readonly value="${esc(pack().id)}"></label><p class="ls-muted">${pack().public?'Anyone signed in can find this public pack.':'This pack is private. Only you can open it.'}</p>`,(pack().owned!==false?btn('share-toggle',pack().public?'Make private':'Make public'):'')+btn('copyid','Copy ID','ls-primary'));
else if(a==='share-toggle'){busy=true;const updated=await persistPack({...pack(),public:!pack().public});packs=packs.map(p=>p.id===updated.id?updated:p);closeModal();render();toast(updated.public?'Pack is now public.':'Pack is now private.')}
else if(a==='copyid'){const val=pack().id;navigator.clipboard?.writeText(val).then(()=>toast('Pack ID copied.')).catch(()=>toast('Select the ID above and press Ctrl+C.'))}
else if(a==='method'){method=b.dataset.value;render()}
else if(a==='scope'){scope=b.dataset.value;render()}
else if(a==='start'||a==='quick'){busy=true;await studyStart();}
else if(a==='backpack'){screen='pack';render();saveState()}
else if(a==='flip'){flipped=true;const flipper=main.querySelector('.ls-flipper');flipper.classList.add('flipped');flipper.querySelector('.ls-front').setAttribute('aria-hidden','true');flipper.querySelector('.ls-back').removeAttribute('aria-hidden');main.querySelector('#ls-answer-controls').innerHTML=answerButtons();main.querySelector('.ls-study-hint').textContent='Rate your answer from memory.';icons()}
else if(a==='check-answer'){answered=true;render()}
else if(a==='restart'){busy=true;await studyStart();}
else if(a==='choose-answer'){const current=studyCards[studyIndex];if(current?.phase!=='choice'||sessionResults[studyIndex]!==null)return;busy=true;await recordAnswer(current.options[+b.dataset.option]===current.back);render()}
else if(a==='postpone')postponeQuestion();
else if(a==='previous-card'||a==='next-card'){if(method==='Absorb'&&(a==='previous-card'||sessionResults[studyIndex]===null))return;if(a==='previous-card'&&studyIndex>0)studyIndex--;else if(a==='next-card'&&studyIndex<studyCards.length)studyIndex++;resetQuestionClock();flipped=false;answered=false;render()}
else if(a==='review-unanswered'){studyIndex=sessionResults.findIndex(v=>v===null);resetQuestionClock();flipped=false;answered=false;render()}
else if(['again','hard','got'].includes(a)){if(!studyCards[studyIndex])return;busy=true;await recordAnswer(a==='got');if(method!=='Absorb'){studyIndex++;resetQuestionClock();flipped=false;answered=false}render()}
else if(a==='close')closeModal();
else if(a==='save'){if(!draft.title.trim()){toast('Your pack needs a title.');return}busy=true;const previous=active,saved=await persistPack(draft);packs=packs.map(p=>p.id===previous?saved:p);active=saved.id;screen='pack';popup='';render();saveState();toast('Learning pack saved.')}
else if(a==='cancel-edit'){if(JSON.stringify(draft)!==JSON.stringify(pack()))dialog('Discard your changes?',`<p>Your saved learning pack will stay as it was.</p>`,btn('close','Keep editing')+btn('discard','Discard changes'));else{screen='pack';render()}}
else if(a==='discard'){closeModal();screen='pack';render()}
else if(a==='newcard'){snapshot();const i=selected<0?draft.cards.length:selected+1;draft.cards.splice(i,0,{front:'',back:''});selected=i;render();main.querySelector(`[data-cell="front"][data-row="${i}"]`)?.focus()}
else if(a==='delete'){snapshot();draft.cards.splice(+b.dataset.row,1);selected=Math.min(selected,draft.cards.length-1);render()}
else if(a==='select'){selected=+b.dataset.row;render()}
else if(a==='undo'&&undo.length){redo.push(clone(draft));draft=undo.pop();selected=Math.min(selected,draft.cards.length-1);render()}
else if(a==='redo'&&redo.length){undo.push(clone(draft));draft=redo.pop();selected=Math.min(selected,draft.cards.length-1);render()}
else if(a==='issues'){popup=popup==='issues'?'':'issues';render()}
else if(a==='jump'){selected=+b.dataset.row;popup='';render();const cell=main.querySelector(`[data-cell="${b.dataset.col}"][data-row="${selected}"]`);cell?.classList.add('ls-highlight');cell?.focus();cell?.scrollIntoView({block:'nearest'})}
else if(a==='import')importDialog();
else if(a==='importfile'){if(screen!=='edit')startEdit();if(screen!=='edit')return;popup='';root.querySelector('#ls-import-input').click()}
else if(a==='preview-paste'){importRows=parseText(modal.querySelector('#ls-paste').value);previewImport()}
else if(a==='confirm-import'){if(draft.cards.length+importRows.length>500){toast('A pack can have up to 500 cards. Reduce this import.');return}snapshot();draft.cards.push(...importRows);closeModal();render();toast('Cards imported. Save to keep your changes.')}
else if(a==='template')await template();
else if(a==='image'&&selected>=0)root.querySelector('#ls-image-input').click();
else if(a==='image-front'||a==='image-back'){snapshot();draft.cards[selected].image=imagePending;draft.cards[selected].side=a==='image-front'?'Front':'Back';closeModal();render()}
else if(a==='image-edit'){selected=+b.dataset.row;const c=draft.cards[selected];dialog('Card image',`<img class="ls-image-preview" src="${c.image}" alt="Card image"><p>Shown on the ${c.side.toLowerCase()}.</p>`,btn('image-switch','Switch side')+btn('image-remove','Remove image')+btn('image-replace','Replace'))}
else if(a==='image-switch'){snapshot();draft.cards[selected].side=draft.cards[selected].side==='Front'?'Back':'Front';closeModal();render()}
else if(a==='image-remove'){snapshot();delete draft.cards[selected].image;closeModal();render()}
else if(a==='image-replace'){closeModal();root.querySelector('#ls-image-input').click()}
else if(a==='find-person'){searchQuery=b.dataset.name;searchTypes=new Set(['users','sets']);screen='search';popup='';render()}
else if(a==='search-filter'){popup=popup==='search-filter'?'':'search-filter';render()}
else if(a==='search-result'){const r=searchItems().find(x=>x.type===b.dataset.type&&x.id===b.dataset.id);if(!r)return;if(r.type==='sets')openPack(r.id);else if(r.type==='questions'){bankPath=r.path;screen='bank';popup='';render()}else dialog(esc(r.title),`<p class="ls-muted">Learning packs by ${esc(r.title)}</p><div class="ls-packs">${packs.filter(p=>p.creator===r.title||p.creatorName===r.title).map(tile).join('')}</div>`)}
else if(a==='bank-open'){bankPath.push(+b.dataset.index);bankLastSelect=-1;render()}
else if(a==='bank-back'){bankPath.pop();bankLastSelect=-1;render()}
else if(a==='bank-crumb'){bankPath=bankPath.slice(0,+b.dataset.depth);bankLastSelect=-1;render()}
else if(a==='bank-set'){const check=main.querySelector(`[data-bank-check="${b.dataset.index}"]`);check.click()}
else if(a==='bank-clear'){bankSelected.clear();bankLastSelect=-1;render()}
else if(a==='bank-practice')toast('Question-bank practice will be connected in the app.');
}catch(error){toast(error.message||'Learning could not connect. Try again.')}finally{busy=false}
});
listen(main,'click',e=>{if(e.target.dataset.bankCheck===undefined)return;const index=+e.target.dataset.bankCheck,want=e.target.checked,nodes=bankChildren();const start=e.shiftKey&&bankLastSelect>=0?Math.min(index,bankLastSelect):index,end=e.shiftKey&&bankLastSelect>=0?Math.max(index,bankLastSelect):index;for(let i=start;i<=end;i++)bankLeaves(nodes[i],[...bankPath,i].join('/')).forEach(l=>want?bankSelected.add(l.key):bankSelected.delete(l.key));bankLastSelect=index;render();icons()});
listen(main,'input',e=>{if(e.target.id==='ls-card-search'){const q=e.target.value.toLowerCase();main.querySelector('#ls-card-list').innerHTML=cardList(pack().cards.filter(c=>(c.front+' '+c.back).toLowerCase().includes(q)));return}if(e.target.dataset.cell){draft.cards[+e.target.dataset.row][e.target.dataset.cell]=e.target.value}if(e.target.dataset.meta)draft[e.target.dataset.meta]=e.target.value});
listen(main,'focusin',e=>{if(e.target.dataset.cell||e.target.dataset.meta){snapshot();if(e.target.dataset.cell){selected=+e.target.dataset.row;main.querySelectorAll('tr[data-row]').forEach(r=>r.classList.toggle('selected',+r.dataset.row===selected));const b=main.querySelector('[data-action="image"]');if(b)b.disabled=false}}});
listen(main,'focusout',e=>{if(e.target.dataset.cell||e.target.dataset.meta){const warn=main.querySelector('[data-action="issues"]');if(warn){warn.querySelector('[data-issue-count]').textContent=issues().length;warn.setAttribute('aria-label',issues().length+' card issues')}for(const a of ['undo','redo']){const b=main.querySelector(`[data-action="${a}"]`);if(b)b.disabled=a==='undo'?!undo.length:!redo.length}}});
listen(main,'paste',e=>{if(!e.target.dataset.cell)return;const text=e.clipboardData.getData('text/plain');if(!text.includes('\t')&&!text.includes('\n'))return;e.preventDefault();snapshot();const rows=text.replace(/\r/g,'').replace(/\n$/,'').split('\n'),start=+e.target.dataset.row,col=e.target.dataset.cell;rows.forEach((l,i)=>{const cells=l.split('\t');while(draft.cards.length<=start+i)draft.cards.push({front:'',back:''});draft.cards[start+i][col]=cells[0]||'';if(col==='front'&&cells.length>1)draft.cards[start+i].back=cells[1]});render();toast(rows.length+' rows pasted.')});
listen(main,'dragstart',e=>{const h=e.target.closest('[data-drag]');if(h){dragFrom=+h.dataset.drag;e.dataTransfer.setData('text/plain',String(dragFrom));e.dataTransfer.effectAllowed='move'}});
listen(main,'dragover',e=>{if(e.target.closest('tr[data-row]'))e.preventDefault()});listen(main,'drop',e=>{const tr=e.target.closest('tr[data-row]');if(!tr||dragFrom<0)return;e.preventDefault();snapshot();const to=+tr.dataset.row;draft.cards.splice(to,0,draft.cards.splice(dragFrom,1)[0]);selected=to;dragFrom=-1;render()});
listen(root,'keydown',e=>{if(e.key==='Escape'){if(modal.innerHTML)closeModal();else if(popup){popup='';render()}return}if(screen!=='edit')return;const cmd=e.ctrlKey||e.metaKey;if(cmd&&['z','y','s'].includes(e.key.toLowerCase())){e.preventDefault();const a=e.key.toLowerCase()==='s'?'save':e.key.toLowerCase()==='y'||e.shiftKey?'redo':'undo';main.querySelector(`[data-action="${a}"]`)?.click()}if(cmd&&e.key.toLowerCase()==='c'&&e.target.dataset.action==='select'&&selected>=0){e.preventDefault();navigator.clipboard?.writeText(draft.cards[selected].front+'\t'+draft.cards[selected].back).catch(()=>toast('Use Ctrl+C inside a cell to copy text.'))}});
listen(root.querySelector('#ls-image-input'),'change',e=>{const f=e.target.files[0];if(!f)return;if(f.size>1024*1024){toast('Choose an image smaller than 1 MB.');e.target.value='';return}const reader=new FileReader();reader.onload=()=>{imagePending=reader.result;imageDialog()};reader.readAsDataURL(f);e.target.value=''});
listen(root.querySelector('#ls-import-input'),'change',async e=>{const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024){toast('Import files smaller than 10 MB.');return}try{if(!XLSX&&f.name.endsWith('.xlsx'))throw Error('Excel import is unavailable. Try pasting your cards.');let rows;if(XLSX){const book=await XLSX.read(await f.arrayBuffer(),{type:'array'});rows=XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]],{header:1,defval:''})}else rows=(await f.text()).trim().split(/\r?\n/).map(l=>l.split(','));if(rows[0]&&/^(front|term)$/i.test(String(rows[0][0]).trim()))rows.shift();importRows=rows.filter(r=>r.some(c=>String(c).trim())).map(r=>({front:String(r[0]||''),back:String(r[1]||'')}));previewImport()}catch(err){toast(err.message)}e.target.value=''});
render();
const syncTimer=demo?null:setInterval(async()=>{if(busy||document.hidden||['edit','study'].includes(screen)||modal.innerHTML||['INPUT','TEXTAREA'].includes(document.activeElement?.tagName))return;try{const before=JSON.stringify(packs);await refreshLibrary();if(controller.signal.aborted)return;if(JSON.stringify(packs)!==before){if(screen==='pack'&&!packs.some(p=>p.id===active))screen='library';render();}}catch{/* Keep the current view available; explicit actions report connection errors. */}},15000);
return ()=>{controller.abort();clearInterval(syncTimer);clearTimeout(toast.timer);host.innerHTML='';};
}
